import pytest

import answer


def test_normalises_within_group():
    out = answer.group_advantages([[0.0, 1.0], [10.0, 20.0, 30.0]])
    assert out[0] == pytest.approx([-1.0, 1.0])
    assert out[1] == pytest.approx([-1.2247449, 0.0, 1.2247449])


def test_zero_variance_group_is_all_zeros():
    assert answer.group_advantages([[5.0, 5.0, 5.0]]) == [[0.0, 0.0, 0.0]]


def test_single_element_group_is_zero():
    assert answer.group_advantages([[3.0]]) == [[0.0]]


def test_empty_cases():
    assert answer.group_advantages([]) == []
    assert answer.group_advantages([[]]) == [[]]


def test_groups_do_not_leak_into_each_other():
    a = answer.group_advantages([[0.0, 1.0]])[0]
    b = answer.group_advantages([[0.0, 1.0], [100.0, 900.0]])[0]
    assert a == pytest.approx(b)


def test_ema_series():
    assert answer.ema([1.0, 2.0, 3.0], 0.5) == pytest.approx([1.0, 1.5, 2.25])
    assert answer.ema([4.0], 1.0) == pytest.approx([4.0])
    assert answer.ema([], 0.3) == []


def test_ema_validates_alpha():
    for bad in (0.0, -0.1, 1.5):
        with pytest.raises(ValueError):
            answer.ema([1.0, 2.0], bad)
